	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	clock := time.Now
	s := &Store{
		db:     db,
		cancel: cancel,
		done:   make(chan struct{}),
