}

// runReaper drives deterministic transfer for every expired lease.
func (s *Store) runReaper(ctx context.Context) {
	defer close(s.done)
	ticker := time.NewTicker(reapInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
