	}
	if err != nil {
		return err
	}

	if _, err := tx.Exec(
		`UPDATE resources
		 SET owner_id = ?, lease_expires_at = ?, reentry_count = 1
		 WHERE resource_id = ?`,
		nextOwner, now.Add(time.Duration(nextLeaseSeconds)*time.Second).UnixMilli(),
		resourceID,
	); err != nil {
		return err
	}
	_, err = tx.Exec(`DELETE FROM waiting_requests WHERE id = ?`, nextID)
	return err
}

